package com.nimbusbill.customer.service; import com.nimbusbill.customer.dto.AiInsightResponse; import com.nimbusbill.customer.entity.*; import com.nimbusbill.customer.repository.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.Instant; import java.util.*;
@Service @Transactional public class AiInsightService{private final CustomerAccessService access;private final PaymentTransactionRepository txs;private final InvoiceRepository invoices;private final AiRecommendationRepository repo;public AiInsightService(CustomerAccessService a,PaymentTransactionRepository t,InvoiceRepository i,AiRecommendationRepository r){access=a;txs=t;invoices=i;repo=r;}@Transactional(readOnly=true) public AiInsightResponse insights(UUID cid,Authentication auth){if(!access.isAdmin(auth)||cid!=null)access.require(auth,cid);var tx=txs.findAll().stream().filter(t->cid==null||t.getCustomer().getId().equals(cid)).toList();var inv=invoices.findAll().stream().filter(i->cid==null||i.getCustomer().getId().equals(cid)).toList();long rejected=tx.stream().filter(t->t.getStatus()==PaymentTransactionStatus.REJECTED||t.getStatus()==PaymentTransactionStatus.FAILED).count(),overdue=inv.stream().filter(i->"OVERDUE".equals(i.getStatus())).count();BigDecimal revenue=inv.stream().filter(i->Set.of("ISSUED","OVERDUE","PAID","DISPUTED").contains(i.getStatus())).map(Invoice::getGrandTotal).reduce(BigDecimal.ZERO,BigDecimal::add);List<String> anomalies=new ArrayList<>(),advice=new ArrayList<>();if(rejected>0){anomalies.add(rejected+" transaction exceptions detected");advice.add("Review validation and product configuration");}if(overdue>0){anomalies.add(overdue+" overdue invoices detected");advice.add("Prioritize collection follow-up");}if(anomalies.isEmpty())anomalies.add("No material anomalies detected");return new AiInsightResponse(rejected,overdue,revenue,revenue,anomalies,advice);}@Transactional(readOnly=true) public List<AiRecommendation> list(){return repo.findAllByOrderByCreatedAtDesc();}public AiRecommendation generate(UUID cid,Authentication auth){var i=insights(cid,auth);AiRecommendation r=new AiRecommendation();r.setCustomerId(cid);r.setCategory(i.overdueInvoices()>0?"COLLECTION":"OPERATIONS");r.setTitle(i.overdueInvoices()>0?"Prioritize overdue collections":"Monitor billing operations");r.setRationale(String.join("; ",i.anomalies()));r.setRecommendedAction(i.recommendations().isEmpty()?"Continue monitoring":String.join("; ",i.recommendations()));r.setCreatedBy(auth==null?"local-admin":auth.getName());return repo.save(r);}public AiRecommendation review(UUID id,String decision,String comment,Authentication auth){if(!Set.of("APPROVED","REJECTED").contains(decision))throw new IllegalArgumentException("Invalid decision");AiRecommendation r=repo.findById(id).orElseThrow();r.setStatus(decision);r.setReviewedBy(auth==null?"local-admin":auth.getName());r.setReviewComment(comment);r.setReviewedAt(Instant.now());return repo.save(r);}}
